var documenterSearchIndex = {"docs":
[{"category":"section","location":"applications/#Application-Examples","page":"Applications","text":"Examples from the applications section of SAGBI and Groebner Bases Detection are written below in Julia, using Oscar.jl and SagbiGbDetection.jl.\n\n# Oscar handles the polynomial rings; SagbiGbDetection handles the\n# Groebner and SAGBI checks.\nusing Oscar\nusing SagbiGbDetection\nusing Combinatorics","title":"Application Examples"},{"category":"section","location":"applications/#Sullivant-Talaska-Ideal","page":"Applications","text":"For the cycle graph on four vertices, the Sullivant-Talaska ideal I_4 is generated by minors of selected cyclic submatrices. The code below detects weights where these generators form a Groebner basis.\n\n# Polynomial ring QQ[s_ij] for an n x n symmetric matrix.\nfunction define_ring(n)\n    variables_R = vec([\"s_$(i)$(j)\" for i in 1:n, j in 1:n])\n    return polynomial_ring(QQ, variables_R)\nend\n\n# Start with an n x n matrix and impose symmetry.\nfunction symmetric_generic_matrix(v, n)\n    generic_matrix = reshape(v, n, n)\n    for i in 1:n\n        for j in 1:i-1\n            generic_matrix[i, j] = generic_matrix[j, i]\n        end\n    end\n    return generic_matrix\nend\n\n# Convert the Julia submatrix before taking its determinant in Oscar.\nfunction determinant_mpoly(submatrix::Matrix)\n    return det(matrix(submatrix))\nend\n\n# All s x s minors, indexed by choices of rows and columns.\nfunction compute_minors(matrix::Matrix{T}, s::Int) where T\n    m, n = size(matrix, 1), size(matrix, 2)\n    if m < s || n < s || s < 1\n        throw(ArgumentError(\"Invalid values for m, n, or s\"))\n    end\n\n    determinants = T[]\n    for rows_combination in Combinatorics.combinations(1:m, s)\n        for cols_combination in Combinatorics.combinations(1:n, s)\n            minor = matrix[rows_combination, cols_combination]\n            push!(determinants, determinant_mpoly(copy(minor)))\n        end\n    end\n    return determinants\nend\n\n# The generators are the 3 x 3 minors of the selected cyclic submatrices.\nfunction k_submatrices_minors(generic_matrix, rows, cols, k)\n    minors_vec = eltype(generic_matrix)[]\n    for i in 1:k\n        sub_matrix = generic_matrix[rows[i], cols[i]]\n        append!(minors_vec, compute_minors(sub_matrix, 3))\n    end\n    return minors_vec\nend\n\n# Symmetric 4 x 4 matrix for the cycle graph.\nn = 4\nR, v = define_ring(n)\ngeneric_matrix = symmetric_generic_matrix(v, n)\n\n# Cyclic 3-row windows.\nrows = Vector{Vector{Int}}(undef, n)\nfor i in 1:n\n    rows[i] = [(j + i - 2) % n + 1 for j in 1:3]\nend\n\n# Matching cyclic 3-column windows.\ncols = Vector{Vector{Int}}(undef, n)\nfor i in 1:n\n    cols[i] = [(j + i + 1) % n + 1 for j in 0:2]\nend\n\n# Detect Groebner weights for the resulting generators.\nG = k_submatrices_minors(generic_matrix, rows, cols, n)\nweight_vectors = weightVectorsRealizingGB(G, R)\nlength(weight_vectors)\n# 9","title":"Sullivant-Talaska Ideal"},{"category":"section","location":"applications/#Minors-Of-A-General-Matrix","page":"Applications","text":"Here the generators are the 2 x 2 minors of a general 3 x 3 matrix.\n\n# Coordinate ring for a generic 3 x 3 matrix.\nT, v = polynomial_ring(QQ, [\n    \"t11\", \"t12\", \"t13\",\n    \"t21\", \"t22\", \"t23\",\n    \"t31\", \"t32\", \"t33\",\n])\n(t11, t12, t13, t21, t22, t23, t31, t32, t33) = v\n\nt_ij = [\n    t11 t12 t13\n    t21 t22 t23\n    t31 t32 t33\n]\n\n# SAGBI weights for the 2 x 2 minors.\nminors = compute_minors(t_ij, 2)\nweightVectorsRealizingSAGBI(minors, T)\n# 6 weight vectors","title":"Minors Of A General Matrix"},{"category":"section","location":"applications/#Truncation-Variety","page":"Applications","text":"The truncation variety V_{1,3} gives an example where no tested term order makes the parametrization a SAGBI basis.\n\n# Coordinate ring for the parametrization.\nS, v = polynomial_ring(QQ, [\n    \"s\", \"z1\", \"z2\", \"z3\", \"z4\", \"z5\",\n    \"z6\", \"z7\", \"z8\", \"z9\", \"z10\",\n])\n(s, z1, z2, z3, z4, z5, z6, z7, z8, z9, z10) = v\n\n# Parametrizing polynomials for V_{1,3}.\nQ = [\n    s,\n    s*z1,\n    s*z2,\n    s*z3,\n    s*z4,\n    s*z5,\n    s*z6,\n    s*z7,\n    s*z8,\n    s*z9,\n    s*(z1*z5 - z2*z4),\n    s*(z1*z6 - z3*z4),\n    s*(z2*z6 - z3*z5),\n    s*(z1*z8 - z2*z7),\n    s*(z1*z9 - z3*z7),\n    s*(z2*z9 - z3*z8),\n    s*(z4*z8 - z5*z7),\n    s*(z4*z9 - z6*z7),\n    s*(z5*z9 - z6*z8),\n    s*(z10 + z1*(z5*z9 - z6*z8) - z2*(z4*z9 - z6*z7) + z3*(z4*z8 - z5*z7)),\n]\n\n# The empty output records that no SAGBI weight was found.\nweightVectorsRealizingSAGBI(Q, S)\n# []","title":"Truncation Variety"},{"category":"section","location":"SagbiGBDetection_examples/#SagbiGbDetection-Examples","page":"Examples","text":"These examples use Oscar.jl polynomial rings and the algorithms from SAGBI and Groebner Bases Detection.\n\nusing Oscar\nusing SagbiGbDetection","title":"SagbiGbDetection Examples"},{"category":"section","location":"SagbiGBDetection_examples/#Groebner-Basis-Detection","page":"Examples","text":"weightVectorsRealizingGB(G, R) returns representative weights for which G is a Groebner basis of its ideal.\n\nR, (x, y, z) = polynomial_ring(QQ, [\"x\", \"y\", \"z\"])\nG = [\n    x^5 + y^3 + z^2 - 1,\n    x^2 + y^2 + z - 1,\n    x^6 + y^5 + z^3 - 1,\n]\n\nweightVectorsRealizingGB(G, R)\n# [[12, 15, 27]]\n\nAn empty list means that no tested term order makes the generators a Groebner basis.\n\nS, (u, v) = polynomial_ring(QQ, [\"u\", \"v\"])\nH = [u^2 + v^2 - 1, 2*u*v - 1]\n\nweightVectorsRealizingGB(H, S)\n# []\n\nFor a fixed weight vector, use BuchbergerCriterion.\n\nBuchbergerCriterion(G, R, [12, 15, 27])\n# true","title":"Groebner Basis Detection"},{"category":"section","location":"SagbiGBDetection_examples/#SAGBI-Basis-Detection","page":"Examples","text":"weightVectorsRealizingSAGBI(F, R) returns representative weights for which F is a SAGBI basis of the subalgebra R[F]. The default verification method, method = :hilbert_series, uses the criterion from Lemma 3.7 and Remark 3.9 of the paper. Theorem 2.0.4 can be checked with method = :initial_ideal. The aliases :hilbert and :initial are also accepted.\n\nR, (x, y, z) = polynomial_ring(QQ, [\"x\", \"y\", \"z\"])\nF = [x + y + z, x*y + x*z + y*z, x*y*z]\n\nweightVectorsRealizingSAGBI(F, R)\n# 6 weight vectors, one for each permutation of [1, 2, 3]\n\nFor a fixed weight vector, use SagbiCriterion.\n\nSagbiCriterion(F, R, [3, 2, 1])\n# true\n\nSagbiCriterion(F, R, [3, 2, 1]; method = :hilbert)\n# true\n\nSagbiCriterion(F, R, [3, 2, 1]; method = :initial_ideal)\n# true\n\nAn empty list means that no tested term order makes the generators a SAGBI basis.\n\nS, (u, v) = polynomial_ring(QQ, [\"u\", \"v\"])\nH = [u + v, u*v, u*v^2]\n\nweightVectorsRealizingSAGBI(H, S)\n# []","title":"SAGBI Basis Detection"},{"category":"section","location":"SagbiGBDetection_examples/#Weight-Representatives","page":"Examples","text":"extractWeightVectors(F) gives the representative weights coming from the relevant normal cones of the Newton polytope.\n\nextractWeightVectors(F)","title":"Weight Representatives"},{"category":"section","location":"#SagbiGbDetection","page":"Home","text":"SagbiGbDetection.jl is a Julia package for Gröbner and SAGBI basis detection.\n\n","title":"SagbiGbDetection"},{"category":"section","location":"#Getting-Started","page":"Home","text":"SagbiGbDetection is a computer algebra package for the Julia programming language, maintained by Viktoriia Borovik, Timothy Duff and Elima Shehu.\n\nhttps://github.com/elimashehu/SagbiGbDetection.jl (Source code)\n\nSagbiGbDetection implements algorithms for detecting whether a given set of polynomials forms a Groebner basis or SAGBI basis with respect to some term order. The implementation uses Oscar.jl.","title":"Getting Started"},{"category":"section","location":"#Installation","page":"Home","text":"Install Julia from https://julialang.org/downloads/.\n\nSagbiGbDetection requires Julia 1.8 or newer. Once the package is registered, install it with:\n\njulia> ]add SagbiGbDetection\n\nUntil registration is complete, install the development version from GitHub:\n\njulia> using Pkg\njulia> Pkg.add(url = \"https://github.com/elimashehu/SagbiGbDetection.jl\")","title":"Installation"},{"category":"section","location":"#Examples","page":"Home","text":"The examples page covers the main Groebner and SAGBI routines. The application examples page gives Julia code for examples from the paper.","title":"Examples"}]
}
